 assert.deepEqual(inventoryBeforeFighter(actual).sort(),baseline.files.map(f=>f.path).sort());
 for(const f of baseline.files)assert.equal(blob(readBeforeFighter(new URL(f.path,root))),f.gitBlob,f.path);
